import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"Code Review 規範","description":"","frontmatter":{},"headers":[],"relativePath":"code-review-spec.md","filePath":"code-review-spec.md"}'),d={name:"code-review-spec.md"};function c(n,e,s,i,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="code-review-規範" tabindex="-1">Code Review 規範 <a class="header-anchor" href="#code-review-規範" aria-label="Permalink to &quot;Code Review 規範&quot;">​</a></h1><p><strong>類型</strong>：spec | <strong>權重</strong>：1</p><p>本文件為<strong>每階段工作後</strong>進行 code review 的檢查標準，目的在讓<strong>規格與專案現況保持一致</strong>。適用對象：<strong>開發者</strong>與 <strong>AI（Coding Agent / Review Agent）</strong>。審查時可依本規範逐項勾選，並在發現偏離時更新對應的 docs / specs。</p><hr><h2 id="_1-目的與使用時機" tabindex="-1">1. 目的與使用時機 <a class="header-anchor" href="#_1-目的與使用時機" aria-label="Permalink to &quot;1. 目的與使用時機&quot;">​</a></h2><ul><li><strong>目的</strong>：確保程式碼、契約、架構文件與實際目錄結構同步；避免規格過時或與實作脫節。</li><li><strong>使用時機</strong>：每階段工作完成後（例如 feature 完成、重構完成、上線前）、或 PR 前自檢／審查時。</li><li><strong>產出</strong>：通過檢查、或產出「待辦：更新 X 文件／修正 Y 違規」清單。當期報告與議題在 <strong>code-review/REPORT.md</strong>、<strong>code-review/issues.md</strong>；待辦應在對應程式位置加 <code>// TODO(CR-xxx): description</code>（ID 為 CR-001 等，見 <a href="./../code-review/README.html">code-review/README.md</a>），並在 issues.md 登錄。</li></ul><hr><h2 id="_2-審查清單" tabindex="-1">2. 審查清單 <a class="header-anchor" href="#_2-審查清單" aria-label="Permalink to &quot;2. 審查清單&quot;">​</a></h2><h3 id="_2-1-分層與依賴方向" tabindex="-1">2.1 分層與依賴方向 <a class="header-anchor" href="#_2-1-分層與依賴方向" aria-label="Permalink to &quot;2.1 分層與依賴方向&quot;">​</a></h3><ul><li>[ ] <strong>Canonical 分層</strong>：<code>specs/</code> 為契約、<code>docs/</code> 為工程知識、<code>AGENTS.md</code> / <code>AGENT_CAPABILITIES.md</code> 為 agent 入口；<code>.cursor/rules</code> 等僅為 tool adapter，不另定義架構／產品 truth。</li><li>[ ] <strong>依賴方向</strong>：符合 <a href="./architecture/repo-layers.html">docs/architecture/repo-layers.md</a>；features 不依賴其他 features；components 不依賴 features；禁止在 component 內直接 <code>fetch(url)</code>。</li><li>[ ] <strong>Route 薄層</strong>：<code>app/routes/*</code> 僅負責 loader/action 與組裝 UI，業務邏輯在 <code>app/features/*</code> 或 <code>app/services/*</code>。</li></ul><p><strong>若違反</strong>：調整程式或補充/修正 <a href="./architecture/repo-layers.html">docs/architecture/repo-layers.md</a>、<a href="./architecture/system-overview.html">docs/architecture/system-overview.md</a>。</p><hr><h3 id="_2-2-契約與-api" tabindex="-1">2.2 契約與 API <a class="header-anchor" href="#_2-2-契約與-api" aria-label="Permalink to &quot;2.2 契約與 API&quot;">​</a></h3><ul><li>[ ] <strong>契約單一來源</strong>：API 的 request/response 形狀以 <code>@ai-search-portal/contracts</code>（<a href="./../packages/shared-contracts/"><code>packages/shared-contracts</code></a>）為準；App 僅經 <code>app/shared/contracts/index.ts</code> re-export；與 <a href="./../specs/api/contract-schema.html">specs/api/contract-schema.md</a>、<a href="./../specs/README.html">specs/README.md</a> 一致。</li><li>[ ] <strong>API 路徑單一來源</strong>：所有 API 路徑從 <code>app/shared/api/paths.ts</code> import，不在 component / hooks / routes 內硬編碼路徑字串。</li><li>[ ] <strong>Handler 對照</strong>：對外 API 在 <a href="./../specs/api/handler-mapping.html">specs/api/handler-mapping.md</a> 有對照、且 <code>app/test/handlers.ts</code> 有對應 MSW handler；新增 API 時兩處皆需更新。</li><li>[ ] <strong>錯誤 response</strong>：若 API 回傳錯誤，形狀與契約一致（如 <code>errorResponseSchema</code>）；見 <a href="./conventions/error-handling.html">docs/conventions/error-handling.md</a>。</li></ul><p><strong>若違反</strong>：補齊或修正 <code>packages/shared-contracts</code>、<code>app/shared/contracts/index.ts</code>、<code>app/shared/api/paths.ts</code>、<code>specs/openapi/openapi.yaml</code>（並 <code>pnpm run codegen:openapi</code>）、<code>specs/api/handler-mapping.md</code>、<code>app/test/handlers.ts</code>，以及 <a href="./conventions/data-test-driven.html">docs/conventions/data-test-driven.md</a> 若有提及流程。</p><hr><h3 id="_2-3-型別與安全" tabindex="-1">2.3 型別與安全 <a class="header-anchor" href="#_2-3-型別與安全" aria-label="Permalink to &quot;2.3 型別與安全&quot;">​</a></h3><ul><li>[ ] <strong>避免裸 <code>any</code></strong>：除在 shared 層單一處（如 <code>submitFormPayload</code> 內對 Remix submit 的型別斷言）並加註 eslint-disable 外，不在 feature 或 component 內使用 <code>as any</code> / <code>any</code>。</li><li>[ ] <strong>Submit payload</strong>：表單／CRUD 提交透過 <code>app/shared/api/submitPayload.ts</code> 的 <code>submitFormPayload</code>，不直接在各 hook 內對 <code>fetcher.submit</code> 做型別斷言。</li></ul><p><strong>若違反</strong>：改為使用 shared 型別或 helper，或將唯一必要斷言集中至 shared 並註明理由。</p><hr><h3 id="_2-4-命名與慣例" tabindex="-1">2.4 命名與慣例 <a class="header-anchor" href="#_2-4-命名與慣例" aria-label="Permalink to &quot;2.4 命名與慣例&quot;">​</a></h3><ul><li>[ ] <strong>資料夾</strong>：<code>app/</code> 下（除 <code>app/routes</code>）資料夾為小寫、無連字號/底線（見 <a href="./conventions/coding-conventions.html">docs/conventions/coding-conventions.md</a>）。</li><li>[ ] <strong>元件檔</strong>：<code>app/components/**/*.tsx</code> 檔名為 PascalCase。</li><li>[ ] <strong>檢查</strong>：<code>pnpm run lint:filenames</code> 通過；<code>pnpm run lint</code>、<code>pnpm run typecheck</code> 通過。</li></ul><p><strong>若違反</strong>：重新命名或修正，並確認 <a href="./conventions/coding-conventions.html">docs/conventions/coding-conventions.md</a> 仍涵蓋當前規則。</p><hr><h3 id="_2-5-文件與規格對齊" tabindex="-1">2.5 文件與規格對齊 <a class="header-anchor" href="#_2-5-文件與規格對齊" aria-label="Permalink to &quot;2.5 文件與規格對齊&quot;">​</a></h3><ul><li>[ ] <strong>架構變更</strong>：目錄結構或分層若有變更，已更新 <a href="./architecture/">docs/architecture/</a>、必要時 <a href="./../AGENTS.html">AGENTS.md</a> / <a href="./../AGENT_CAPABILITIES.html">AGENT_CAPABILITIES.md</a>。</li><li>[ ] <strong>產品／領域</strong>：功能或領域模型變更時，已更新 <a href="./product/">docs/product/</a> 對應文件。</li><li>[ ] <strong>入口與索引</strong>：根目錄 <code>docs/ARCHITECTURE.md</code>、<code>docs/CONVENTIONS.md</code>、<code>docs/DEVELOPMENT.md</code> 的連結仍正確；<a href="./README.html">docs/README.md</a> 一覽與實際 docs 結構一致。</li><li>[ ] <strong>無殘留</strong>：無指向已刪除或搬移文件的連結（如舊 <code>.cursor/wiki</code>）；無過時路徑或檔名。</li></ul><p><strong>若違反</strong>：更新對應 docs、specs 或根目錄 stub；修正壞鏈。</p><hr><h3 id="_2-6-架構可套用性-若本-repo-作為範本" tabindex="-1">2.6 架構可套用性（若本 repo 作為範本） <a class="header-anchor" href="#_2-6-架構可套用性-若本-repo-作為範本" aria-label="Permalink to &quot;2.6 架構可套用性（若本 repo 作為範本）&quot;">​</a></h3><ul><li>[ ] <strong>README</strong>：若本專案作為技術架構範本，README 已註明「架構範本與可套用性」並連結至 <code>docs/README.md</code>、<code>AGENTS.md</code>、<code>AGENT_CAPABILITIES.md</code>。</li><li>[ ] <strong>Tool adapter</strong>：<code>.cursor/rules</code> 等僅指向 canonical 來源並補充工具專用格式，不覆寫專案 truth。</li></ul><p><strong>若違反</strong>：更新 README 或 adapter 內容，使與 <a href="./../AGENT_CAPABILITIES.html">AGENT_CAPABILITIES.md</a> 的 Extension Policy 一致。</p><hr><h2 id="_3-變更時應同步更新的對照" tabindex="-1">3. 變更時應同步更新的對照 <a class="header-anchor" href="#_3-變更時應同步更新的對照" aria-label="Permalink to &quot;3. 變更時應同步更新的對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>變更類型</th><th>應更新的檔案／位置</th></tr></thead><tbody><tr><td>新增／變更 API</td><td><code>packages/shared-contracts</code>、<code>specs/openapi/openapi.yaml</code>、<code>app/shared/contracts/index.ts</code>、<code>app/shared/api/paths.ts</code>、<code>specs/api/handler-mapping.md</code>、<code>app/test/handlers.ts</code>；必要時 <a href="./conventions/data-test-driven.html">docs/conventions/data-test-driven.md</a></td></tr><tr><td>目錄或分層調整</td><td><a href="./architecture/repo-layers.html">docs/architecture/repo-layers.md</a>、<a href="./architecture/system-overview.html">docs/architecture/system-overview.md</a>、必要時 AGENTS.md / AGENT_CAPABILITIES.md</td></tr><tr><td>錯誤處理慣例</td><td><a href="./conventions/error-handling.html">docs/conventions/error-handling.md</a>、契約內 error schema、specs 註明</td></tr><tr><td>命名／慣例調整</td><td><a href="./conventions/coding-conventions.html">docs/conventions/coding-conventions.md</a>、必要時 <code>lint:filenames</code> 規則</td></tr><tr><td>產品／領域變更</td><td><a href="./product/">docs/product/</a> 對應文件、<a href="./README.html">docs/README.md</a> 一覽</td></tr></tbody></table><hr><h2 id="_4-給-ai-coding-review-agent-的注意事項" tabindex="-1">4. 給 AI（Coding / Review Agent）的注意事項 <a class="header-anchor" href="#_4-給-ai-coding-review-agent-的注意事項" aria-label="Permalink to &quot;4. 給 AI（Coding / Review Agent）的注意事項&quot;">​</a></h2><ul><li><strong>Canonical 優先</strong>：審查結論以本規範與 <code>docs/</code>、<code>specs/</code>、<code>AGENTS.md</code>、<code>AGENT_CAPABILITIES.md</code> 為準；tool-specific 設定不覆寫上述來源。</li><li><strong>產出</strong>：審查後可產出「通過」或「待辦清單」（列出違規項與建議更新的文件／程式位置）。</li><li><strong>修改權限</strong>：Review Agent 僅建議修正，不直接改程式；Coding Agent 依授權可一併更新程式與對應文件以符合本規範。</li></ul><hr><h2 id="_5-相關文件" tabindex="-1">5. 相關文件 <a class="header-anchor" href="#_5-相關文件" aria-label="Permalink to &quot;5. 相關文件&quot;">​</a></h2><ul><li><a href="./../code-review/README.html">code-review/README.md</a> — Code review 機制、TODO 格式、一致性檢查</li><li><a href="./conventions/doc-todo-governance.html">conventions/doc-todo-governance.md</a> — 文件同步與 TODO 治理總表</li><li><a href="./README.html">docs/README.md</a> — docs 目錄索引</li><li><a href="./../AGENTS.html">AGENTS.md</a> — Coding agent 入口與流程</li><li><a href="./../AGENT_CAPABILITIES.html">AGENT_CAPABILITIES.md</a> — 能力邊界與 agent class</li><li><a href="./conventions/coding-conventions.html">docs/conventions/coding-conventions.md</a> — 命名與慣例</li><li><a href="./conventions/data-test-driven.html">docs/conventions/data-test-driven.md</a> — Spec→Contract→Mock→Test→UI</li><li><a href="./conventions/error-handling.html">docs/conventions/error-handling.md</a> — 錯誤與邊界處理</li></ul>',40)])])}const g=o(d,[["render",c]]);export{m as __pageData,g as default};
